import os
import sys
import base64
import tempfile

POLITO_LOGO_B64 = """"""
APP_ICON_B64 = """"""


def get_logo_bytes(custom_path=""):
    if custom_path and os.path.isfile(custom_path):
        try:
            with open(custom_path, "rb") as f:
                return f.read()
        except Exception as e:
            print("Error loading custom logo:", e)
    return base64.b64decode(POLITO_LOGO_B64)


def get_app_icon_path():
    # If icon.ico exists next to script/binary
    base_dir = getattr(sys, "_MEIPASS", os.path.dirname(os.path.abspath(__file__)))
    candidate = os.path.join(base_dir, "assets", "icon.ico")
    if os.path.isfile(candidate):
        return candidate
    candidate2 = os.path.join(os.path.dirname(base_dir), "assets", "icon.ico")
    if os.path.isfile(candidate2):
        return candidate2

    # Fallback to temp file
    temp_ico = os.path.join(tempfile.gettempdir(), "slide_note_icon.ico")
    if not os.path.exists(temp_ico):
        try:
            with open(temp_ico, "wb") as f:
                f.write(base64.b64decode(APP_ICON_B64))
        except Exception:
            pass
    return temp_ico if os.path.exists(temp_ico) else None
